sys_script_client.script:
function onLoad() {
    var currentState = g_form.getValue('state');

    // STRY0019513 04/02/26 - Limit state options when Complete or Reopened
    // Complete = 400, Reopened = 8
    if (currentState == '400') {
        // From Complete, can only stay Complete or go to Reopened and Cancelled
        removeAllStateOptionsExcept(['400', '8', '7']);
    } else if (currentState == '8') {
        // From Reopened, can only stay Reopened or go to Complete or Cancelled
        removeAllStateOptionsExcept(['8', '400', '7']);
    } else if (currentState == '7') {
        // Add handling for state '7' Cancelled
        removeAllStateOptionsExcept(['7']);
    }
}

function removeAllStateOptionsExcept(allowedValues) {
    var stateField = g_form.getControl('state');
    if (!stateField) return;

    for (var i = stateField.options.length - 1; i >= 0; i--) {
        var optionValue = stateField.options[i].value;
        if (allowedValues.indexOf(optionValue) === -1) {
            g_form.removeOption('state', optionValue);
        }
    }
}
